package com.bank.routing;

import java.math.BigDecimal;
import java.util.Map;
import java.util.logging.Logger;

public class EventRouter {
    private static final Logger log = Logger.getLogger(EventRouter.class.getName());
    private final Map<String, Account> accounts;

    public EventRouter(Map<String, Account> accounts) { this.accounts = accounts; }

    // Accepts ANY object, including null. instanceof does the null check AND the
    // type check in one step: a null event simply falls through to "rejected".
    public String route(Object event) {
        // Pattern matching: 'tr' is bound ONLY when event is a non-null TransferRequest.
        if (event instanceof TransferRequest tr && tr.getAmount().signum() > 0) {
            Account from = accounts.get(tr.getFromId());
            Account to = accounts.get(tr.getToId());
            from.debit(tr.getAmount());
            to.credit(tr.getAmount());
            log.info(() -> "Transfer " + tr.getAmount() + " from " + tr.getFromId()
                    + " to " + tr.getToId() + " SUCCESS");
            return "ACCEPTED";
        }
        // Reaches here for wrong type AND for null — no NullPointerException possible.
        log.warning(() -> "Rejected event: " + (event == null ? "null" : event.getClass().getSimpleName()));
        return "REJECTED";
    }
}
