package com.bank.routing;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class NullSafeInstanceofDemo {
    private static final Logger log = Logger.getLogger(NullSafeInstanceofDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Direct proof of the rule: null instanceof AnyType is false, no throw.
        Object nothing = null;
        log.info(() -> "null instanceof TransferRequest = " + (nothing instanceof TransferRequest));
        log.info(() -> "null instanceof Account         = " + (nothing instanceof Account));

        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));
        Map<String, Account> accounts = new HashMap<>();
        accounts.put(rajesh.getAccountId(), rajesh);
        accounts.put(priya.getAccountId(), priya);

        EventRouter router = new EventRouter(accounts);

        // 1) valid transfer request
        log.info(() -> "Result: " + router.route(
                new TransferRequest("SAV2001", "CUR3001", new BigDecimal("50000"))));
        // 2) wrong type
        log.info(() -> "Result: " + router.route("this is not an event"));
        // 3) explicit null — handled gracefully, no crash
        log.info(() -> "Result: " + router.route(null));

        log.info(() -> "Final -> Rajesh=" + rajesh.getBalance() + " Priya=" + priya.getBalance());
    }
}
